const sha = x => crypto.createHash('sha256').update(x).digest('hex');
const assert = (x,m) => { if (!x) throw Error(m); };
const base='ff1836e293a2a5cff69773525c347b55deb67dfb';
const prep='bdf5cd8029dc89ad21b10fe58234a3960b4057cd';
