const mb=git('show',`${anchor}:${manifest}`);
assert(mb.equals(git('show',`HEAD:${manifest}`)),'manifest blob changed');
assert(sha(mb)==='022590d076f1e6a972b445b8696c56f83acccfebbaf7e1f30475a388e18e44a4','manifest hash');
assert(JSON.parse(mb).baseCommit===base,'manifest base');
assert(git('show',`${anchor}:${wp}`).toString().includes(`](../${manifest})`),'historical link');
const report={base,prep,anchor,source,manifest:{blob:str('rev-parse',`HEAD:${manifest}`),sha256:sha(mb),workingRawSha256:sha(fs.readFileSync(manifest)),byteProfile:'Canonical Git LF; existing Windows checkout is core.autocrlf=true. No protected working files rewritten.'},port:[],protected:[],workflowDiff:str('diff',base,prep,'--','.github/workflows/validate.yml')};
for (const [p,old,target] of pairs) {
 for(const ref of [base,prep,'d90e798dd9b26d3f152f3b0c2d1d52cae641eb16','a2e26a658a2bcdd47002698c150cb5736d9760da']) assert(str('rev-parse',`${ref}:${p}`)===old,`context ${p} ${ref}`);
 assert(str('hash-object',p)===old,`working context ${p}`);
 assert(str('rev-parse',`${source}:${p}`)===target,`target ${p}`);
 report.port.push({path:p,oldBlob:old,targetBlob:target,targetSha256:sha(git('show',`${source}:${p}`)),numstat:str('diff','--numstat',base,source,'--',p)});
}
const paths=str('ls-tree','-r','--name-only',base).split('\n').filter(p=>p.startsWith('Assets/')||p.startsWith('Packages/')||p.startsWith('ProjectSettings/')||p.startsWith('ARCHITECTURE/')||p.startsWith('DECISIONS/')||p.startsWith('tools/')||p.startsWith('Content/Localization/')||p.startsWith('Content/Reviews/text-library/WP-036/')||p==='.github/workflows/unity.yml');
for(const p of paths) {
 const b=str('rev-parse',`${base}:${p}`), h=str('rev-parse',`HEAD:${p}`), w=str('hash-object',p);
 // Existing preparation reports/README were authorized; all other protected files must match.
 if (p.endsWith('/README.md')||p.endsWith('/COPY_REWORK_HANDOVER.md')) continue;
 assert(b===h&&h===w,`protected file changed ${p}`);
 report.protected.push({path:p,blob:b});
}
const text=git('show',`${base}:Content/Localization/source/de-DE.json`);
assert(sha(text)==='4458cd9214ed788f69cf3816c39835393d4038bd87f6b262c52ad2b86146d53c','accepted source hash');
report.acceptedSourceSha256=sha(text);
